import{fetchCohortJSON}from'./current-cohort-loader.js';
const $=id=>document.getElementById(id),h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),labels={all:'First 1,000 · all splits',development:'Development',holdout:'Original holdout',holdout049:'Fresh holdout',holdout056:'Expansion holdout',grok075:'Grok 1,000'};let d,directory,page=25;const study=['095','096','097'].includes(new URL(location.href).searchParams.get('study'))?new URL(location.href).searchParams.get('study'):'097';
function plot(s,bi){const c=s.curves.targeted[bi],old=s.curves.previous[bi],staged=s.staged[bi],x=n=>48+n/60*500,y=n=>230-n/s.models*200,line=(arm,key)=>s.curves[arm].map((p,i)=>(i?'L':'M')+x(p.budget)+','+y(p[key])).join(' '),compare=$('compare').checked;if(!s.typed)return`<article class="feature"><h2>${h(labels[s.cohort])} · ${s.models}</h2><p><b>Not evaluable.</b> No structured profile facts for simulated follow-ups.</p></article>`;return`<article class="feature"><h2>${h(labels[s.cohort])}</h2><p>${s.typed} / ${s.models} ${study==='097'?'profiles reviewed; unstated preferences stay unknown.':'have structured preference facts.'}</p><div class="totals"><div><strong>${c.top} / ${s.models}</strong>Supported Top</div><div><strong>${c.degree}</strong>College / graduate Top</div></div><div style="overflow:auto"><svg viewBox="0 0 580 275" style="width:100%;min-width:440px" role="img" aria-label="${h(labels[s.cohort])} coverage versus follow-ups">${[0,.25,.5,.75,1].map(v=>`<line x1="48" x2="548" y1="${y(v*s.models)}" y2="${y(v*s.models)}" stroke="#ccd8cd"/><text x="5" y="${y(v*s.models)+4}" fill="currentColor" font-size="14">${v*100}%</text>`).join('')}${[0,12,24,36,60].map(v=>`<text x="${x(v)}" y="253" text-anchor="middle" fill="currentColor" font-size="14">${v}</text>`).join('')}<path d="${line('targeted','top')}" fill="none" stroke="#22845d" stroke-width="3"/><path d="${line('targeted','degree')}" fill="none" stroke="#3269c4" stroke-width="3"/>${compare?`<path d="${line('previous','top')}" fill="none" stroke="#22845d" stroke-dasharray="5 5"/><path d="${line('previous','degree')}" fill="none" stroke="#3269c4" stroke-dasharray="5 5"/>`:''}<line x1="${x(c.budget)}" x2="${x(c.budget)}" y1="20" y2="230" stroke="currentColor" opacity=".4"/></svg></div><p>${(c.asked/s.models).toFixed(1)} questions/model actually asked · ${(c.unknown/Math.max(1,c.asked)*100).toFixed(1)}% unknown.</p><p><b>Checkpoint stop:</b> ${(staged.asked/s.models).toFixed(1)} follow-ups/model · ${staged.top} Top · ${staged.degree} college / graduate Top. Stops once a Top and any supported degree option coexist; no extra evidence is granted.</p><p>Any supported college / graduate option: ${c.allDegree}.</p><p>${study==='097'?'Before legacy profile structuring:':study==='096'?'Before binding repairs at this budget:':'Prior fresh selector at this budget:'} ${old.top} Top · ${old.degree} college Top.</p><p>Of ${s.burden.oldTop} previously covered models: ${c.recoveredModels} have a fresh Top; ${c.sameCareerTop} recover a former Top career.</p></article>`;}
function render(){const bi=+$('budget').value,b=d.budgets[bi],cohort=$('cohort').value,s=d.summary.find(s=>s.cohort===cohort),g=d.summary.find(s=>s.cohort==='grok075');$('total').textContent=`60 profiler + up to ${b} follow-ups = up to ${60+b} interest questions. Lifestyle choices are separate.${d.profileReview?' '+d.profileReview.models+' legacy profiles reviewed · '+d.profileReview.activeFacts+' source-cited fact mappings · '+d.profileReview.withoutMappedFacts+' remain too broad for current predicates.':''}`;$('plots').innerHTML=plot(s,bi)+plot(g,bi);$('splits').innerHTML=d.summary.filter(s=>!['all','grok075'].includes(s.cohort)).map(s=>`<p><b>${h(labels[s.cohort])} · ${s.models}:</b> ${s.typed?`${s.curves.targeted[bi].top} Top · ${s.curves.targeted[bi].degree} college / graduate Top`:'Not evaluable — no typed preference facts'}</p>`).join('');if(d.audit){let panel=document.getElementById('audit096');if(!panel){panel=document.createElement('details');panel.id='audit096';$('plots').after(panel);}panel.innerHTML='<summary>Why are answers unknown?</summary><p>'+h(d.audit.window)+'</p>'+d.audit.summary.filter(a=>[cohort,'grok075'].includes(a.cohort)).map(a=>`<p><b>${h(labels[a.cohort])}:</b> ${a.beforeUnknown} → ${a.afterUnknown} unknown / ${a.questions} identical questions. ${a.resolvedYes} supported Yes; ${a.resolvedNo} explicit No. ${a.afterReasons['missing-binding']||0} still unmapped; ${a.afterReasons['unmeasured-preference']||0} unmeasured; ${a.afterReasons['no-structured-profile']||0} missing profile facts.</p>`).join('')+'<h3>Remaining question gaps · development only</h3>'+d.audit.questions.slice(0,12).map(q=>`<p><b>${h(q.prompt)}</b><br>${q.afterUnknown} / ${q.asked} remain unknown${q.causes?' · '+Object.entries(q.causes).map(([k,n])=>n+' '+h(k.replaceAll('-',' '))).join(' · '):''}${q.needed.length?' · Needs explicit '+q.needed.slice(0,3).map(x=>h(x[0].slice(2).replaceAll('-',' '))).join(', '):' · Binding or unmeasured context needs review'}</p>`).join('');}$('burden').innerHTML='<p>That was an accumulated synthetic answer set, not a fresh student journey. Counts below exclude the 60 profiler answers and lifestyle choices.</p>'+d.summary.filter(s=>['all','grok075'].includes(s.cohort)).map(s=>`<p><b>${h(labels[s.cohort])}:</b> median ${s.burden.median} follow-ups (${s.burden.minimum}–${s.burden.maximum}); median ${60+s.burden.median} interest answers total. ${s.burden.oldTop} saved Top, ${s.burden.oldDegree} saved college / graduate Top. ${s.burden.oldTopWithoutTyped} covered models previously lacked typed facts; source review does not reproduce unsupported accumulated answers.</p>`).join('');
const query=$('search').value.toLowerCase(),issue=$('issue').value,group=$('group').value,rs=d.models.map((m,i)=>({m,p:directory.rows[i],cohort:d.cohorts[m[0]],top:!!(m[2]&(1<<bi)),degree:!!(m[3]&(1<<bi))})).filter(r=>(r.cohort==='grok075'||(cohort==='all'?r.cohort!=='grok075':r.cohort===cohort))&&(group==='both'||group==='grok'&&r.cohort==='grok075'||group==='first'&&r.cohort!=='grok075')&&(!query||(r.p.id+' '+r.p.name).toLowerCase().includes(query))&&(issue==='all'||issue==='evaluable'&&r.m[1]||issue==='untyped'&&!r.m[1]||r.m[1]&&(issue==='noTop'&&!r.top||issue==='noDegree'&&!r.degree||issue==='lostTop'&&!!(r.m[4]&(1<<bi))&&!r.top||issue==='lostDegree'&&!!(r.m[5]&(1<<bi))&&!r.degree)));rs.sort((a,b)=>Number(b.top)-Number(a.top));$('count').textContent=`${rs.length} ${rs.length===1?'model':'models'} · showing ${Math.min(page,rs.length)}${['all','evaluable'].includes(issue)&&rs.some(r=>r.top)?' · Supported Top first':''}`;$('models').innerHTML=rs.slice(0,page).map(r=>{const changes=r.m[7].filter(c=>c[0]<=bi),ids=changes.at(-1)?.[1]||[];return`<tr><td><b>${h(r.p.name)}</b><br>${h(r.p.id)}<br>${h(labels[r.cohort])}${study==='097'&&!/^(scale056-|grok075-)/.test(r.p.id)?`<br><a href="/developer/legacy-facts-097.html?model=${encodeURIComponent(r.p.id)}">Profile facts</a>`:''}</td><td>${!r.m[1]?'Not evaluable — needs structured profile facts':ids.length?ids.map(i=>h(d.careers[i][1])).join('<br>'):'No supported Top yet'}</td><td>${!r.m[1]?'Not evaluable':r.degree?'Yes':'Not yet'}</td><td>${Math.min(b,r.m[6])} follow-ups<br>${60+Math.min(b,r.m[6])} interest questions total</td></tr>`;}).join('');$('more').hidden=page>=rs.length;}
try{[d,directory]=await Promise.all([fetchCohortJSON('/developer/evidence-'+study+'.json.gz'),fetchCohortJSON('/developer/current-students-091.json.gz')]);document.querySelector('.eyebrow').textContent='RESEARCH 0.'+study.slice(1)+' · LIVE FLOW UNCHANGED';if(study!=='097'){const current=document.createElement('a');current.href='/developer/fresh-start-095.html?study=097';current.textContent='Current study 0.97 →';document.querySelector('nav').append(current);}if(study!=='095')$('compare').nextSibling.textContent=study==='097'?' Compare before legacy profiles were structured (dashed)':' Compare before binding repairs (dashed)';if(study!=='095'){const base=await fetchCohortJSON('/developer/evidence-095.json.gz');if(study==='097'){const prior=await fetchCohortJSON('/developer/evidence-096.json.gz');if(prior.extends!=='evidence-095'||prior.directoryHash!==base.directoryHash)throw Error('Research baseline mismatch.');base.careers.push(...prior.careerAdditions);base.models=base.models.map(m=>[m[0],m[1],m[2],m[3],m[2],m[3],m[6],m[7]]);for(const[i,m]of prior.modelPatches)base.models[i]=m;}if(d.extends!==(study==='097'?'evidence-096':'evidence-095')||base.directoryHash!==d.directoryHash)throw Error('Research baseline mismatch.');$('issue').insertAdjacentHTML('beforeend','<option value="lostTop">Lost Top versus before change</option><option value="lostDegree">Lost college Top versus before change</option>');d.careers=[...base.careers,...d.careerAdditions];d.models=base.models.map(m=>[m[0],m[1],m[2],m[3],m[2],m[3],m[6],m[7]]);for(const[i,m]of d.modelPatches)d.models[i]=m;}const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(directory.rows.map(r=>r.id)))),hash=[...new Uint8Array(bytes)].map(v=>v.toString(16).padStart(2,'0')).join('');if(hash!==d.directoryHash)throw Error('Model directory version mismatch; reload the page.');$('budget').innerHTML=d.budgets.map((b,i)=>`<option value="${i}" ${b===12?'selected':''}>${b} follow-ups · ${60+b} interest questions total</option>`).join('');$('issue').insertAdjacentHTML('afterbegin','<option value="evaluable">Evaluable models</option>');$('issue').value='evaluable';const params=new URL(location.href).searchParams;if(params.has('budget')&&d.budgets.includes(Number(params.get('budget'))))$('budget').value=String(d.budgets.indexOf(Number(params.get('budget'))));if([...$('cohort').options].some(o=>o.value===params.get('cohort')))$('cohort').value=params.get('cohort');if(params.get('model'))$('search').value=params.get('model');if(study==='097'){document.querySelector('nav').insertAdjacentHTML('beforeend','<a href="/developer/legacy-facts-097.html">Inspect structured profile facts →</a>');}$('limits').innerHTML=d.limits.map(l=>`<li>${h(l)}</li>`).join('');render();for(const id of['budget','cohort','search','issue','compare','group'])$(id).addEventListener('input',()=>{page=25;render();});$('more').onclick=()=>{page+=25;render();};}catch(e){$('plots').textContent=e.message;}
